28	import org.slf4j.Logger;
29	import org.slf4j.LoggerFactory;
30	import org.springframework.http.HttpHeaders;
31	import org.springframework.http.HttpStatus;
32	import org.springframework.http.ResponseEntity;
33	import org.springframework.samples.petclinic.mapper.OwnerMapper;
34	import org.springframework.samples.petclinic.mapper.PetMapper;
35	import org.springframework.samples.petclinic.mapper.VisitMapper;
36	import org.springframework.samples.petclinic.model.Owner;
37	import org.springframework.samples.petclinic.model.Pet;
38	import org.springframework.samples.petclinic.model.Visit;
39	import org.springframework.samples.petclinic.rest.api.OwnersApi;
40	import org.springframework.samples.petclinic.rest.controller.AddressNormalizer;
41	import org.springframework.samples.petclinic.rest.controller.TelephoneNormalizer;
42	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
43	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
44	import org.springframework.samples.petclinic.rest.dto.PetDto;
45	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
46	import org.springframework.samples.petclinic.rest.dto.VisitDto;
47	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
48	import org.springframework.samples.petclinic.service.ClinicService;
49	import org.springframework.security.access.prepost.PreAuthorize;
50	import org.springframework.web.bind.annotation.CrossOrigin;
51	import org.springframework.web.bind.annotation.RequestMapping;
52	import org.springframework.web.bind.annotation.RestController;
53	import org.springframework.web.util.UriComponentsBuilder;
54	
55	import jakarta.transaction.Transactional;
56	
57	/**
58	 * @author Vitaliy Fedoriv
59	 */
60	
61	@RestController
62	@CrossOrigin(exposedHeaders = "errors, content-type")
63	@RequestMapping("/api")
64	public class OwnerRestControllerV1 implements OwnersApi {
65	
66	    /** Minimal syntactic check for an email address: a non-empty local part, a single
67	     *  '@', and a dotted domain, none containing whitespace or a second '@'. */
68	    private static final Pattern EMAIL_PATTERN =
69	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
70	
71	    /** Dedicated audit logger; emits an audit line on successful owner create. */
72	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
73	
74	    private final ClinicService clinicService;
75	
76	    private final OwnerMapper ownerMapper;
77	
78	    private final PetMapper petMapper;
79	
80	    private final VisitMapper visitMapper;
81	
82	    private final TelephoneNormalizer telephoneNormalizer;
83	
84	    private final AddressNormalizer addressNormalizer;
85	
86	    public OwnerRestControllerV1(ClinicService clinicService,
87	                                 OwnerMapper ownerMapper,
88	                                 PetMapper petMapper,
89	                                 VisitMapper visitMapper,
90	                                 TelephoneNormalizer telephoneNormalizer,
91	                                 AddressNormalizer addressNormalizer) {
92	        this.clinicService = clinicService;
93	        this.ownerMapper = ownerMapper;
94	        this.petMapper = petMapper;
95	        this.visitMapper = visitMapper;
96	        this.telephoneNormalizer = telephoneNormalizer;
97	        this.addressNormalizer = addressNormalizer;
98	    }
99	
100	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
101	    @Override
102	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
103	        Collection<Owner> owners;
104	        if (lastName != null) {
105	            owners = this.clinicService.findOwnerByLastName(lastName);
106	        } else {
107	            owners = this.clinicService.findAllOwners();
108	        }
109	        if (owners.isEmpty()) {
110	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
111	        }
112	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
113	    }
114	
115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
118	        Owner owner = this.clinicService.findOwnerById(ownerId);
119	        if (owner == null) {
120	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
121	        }
122	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
123	    }
124	
125	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
126	    @Override
127	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
128	        HttpHeaders headers = new HttpHeaders();
129	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
130	        if (owner.getRegistrationDate() == null) {
131	            owner.setRegistrationDate(LocalDate.now());
132	        }
133	        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
134	        LocalDate registrationDate = owner.getRegistrationDate();
135	        long ownersCreatedThatDay = this.clinicService.findAllOwners().stream()
136	            .map(Owner::getRegistrationDate)
137	            .filter(registrationDate::equals)
138	            .count();
139	        if (ownersCreatedThatDay >= 100) {
140	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
141	        }
142	        String address = addressNormalizer.normalize(owner.getAddress());
143	        if (address.isBlank()) {
144	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
145	        }
146	        owner.setAddress(address);
147	        String telephone = telephoneNormalizer.normalize(owner.getTelephone());
148	        if (telephone == null) {
149	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
150	        }
151	        if (!telephoneNormalizer.hasValidNationalNumberLength(telephone)) {
152	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
153	        }
154	        owner.setTelephone(telephone);
155	        String email = owner.getEmail();
156	        if (email != null) {
157	            email = email.trim();
158	            if (!EMAIL_PATTERN.matcher(email).matches()) {
159	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
160	            }
161	            owner.setEmail(email.toLowerCase(Locale.ROOT));
162	        }
163	        // The owner's telephone and email are now in their canonical, stored form.
164	        // Establish the household id before the duplicate check so the candidate's whole
165	        // identity key can be compared against the existing owners': only an owner that
166	        // deliberately shares an existing household (same normalized last name and address)
167	        // is assigned that household's shared id; a plain new owner has no household id, so
168	        // its identity key is decided by telephone and email alone.
169	        String lastNameKey = normalizeIdentity(owner.getLastName());
170	        String addressKey = addressNormalizer.normalize(owner.getAddress());
171	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())
172	                && householdExists(lastNameKey, addressKey)) {
173	            owner.setHouseholdId(householdId(lastNameKey, addressKey));
174	        }
175	        if (isDuplicateOwner(owner)) {
176	            return new ResponseEntity<>(HttpStatus.CONFLICT);
177	        }
178	        String cityKey = normalizeIdentity(owner.getCity());
179	        long ownersInCity = this.clinicService.findAllOwners().stream()
180	            .filter(existing -> normalizeIdentity(existing.getCity()).equals(cityKey))
181	            .count();
182	        if (ownersInCity >= 50) {
183	            return new ResponseEntity<>(HttpStatus.CONFLICT);
184	        }
185	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
186	        int namesakeCount = (int) this.clinicService.findAllOwners().stream()
187	            .filter(existing -> owner.getFirstName().equalsIgnoreCase(existing.getFirstName())
188	                && owner.getLastName().equalsIgnoreCase(existing.getLastName()))
189	            .count();
190	        owner.setNamesakeCount(namesakeCount);
191	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
192	        owner.setBulkSignupWarning(ownersCreatedThatDay > 80);
193	        this.clinicService.saveOwner(owner);
194	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
195	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
196	            ownerMapper.membershipLevel(owner));
197	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
198	        headers.setLocation(UriComponentsBuilder.newInstance()
199	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
200	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
201	    }
202	
203	    /**
204	     * Whether {@code candidate} collides with an already-registered owner under the single
205	     * identity rule enforced on create. This is the one point at which a new owner is
206	     * rejected as a duplicate (HTTP 409): all duplicate detection is consolidated into the
207	     * derived {@link OwnerMapper#identityKey identityKey} — the normalized telephone, the
208	     * email (or an empty string when absent) and the householdId joined by '|'. The
209	     * candidate clashes only when its WHOLE identityKey equals an existing owner's; because
210	     * the telephone is part of the key, two members of the same household (same householdId)
211	     * with different telephones have different identityKeys and are both allowed.
212	     *
213	     * <p>The candidate arrives with its telephone and email already normalized and its
214	     * household id already derived, and each existing owner is stored in the same canonical
215	     * form, so an identityKey match means the two owners are genuinely the same identity.
216	     *
217	     * @param candidate the fully-normalized owner about to be created
218	     * @return {@code true} if an existing owner already occupies the candidate's identityKey
219	     */
220	    private boolean isDuplicateOwner(Owner candidate) {
221	        String identityKey = OwnerMapper.identityKey(candidate);
222	        return this.clinicService.findAllOwners().stream()
223	            .map(OwnerMapper::identityKey)
224	            .anyMatch(identityKey::equals);
225	    }
226	
227	    /**
228	     * Whether an existing owner already belongs to the household identified by the given
229	     * normalized last name and address, so a new owner flagged {@code sharesHousehold} has a
230	     * household to join.
231	     */
232	    private boolean householdExists(String lastNameKey, String addressKey) {
233	        return this.clinicService.findAllOwners().stream()
234	            .anyMatch(existing -> normalizeIdentity(existing.getLastName()).equals(lastNameKey)
235	                && addressNormalizer.normalize(existing.getAddress()).equals(addressKey));
236	    }
237	
238	    /**
239	     * Normalize a value for household-identity comparison: null becomes an empty
240	     * string, surrounding whitespace is trimmed, internal whitespace runs collapse
241	     * to a single space, and the result is lower-cased.
242	     */
243	    private static String normalizeIdentity(String value) {
244	        if (value == null) {
245	            return "";
246	        }
247	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
248	    }
249	
250	    /**
251	     * Build the stable, shared household identifier for an owner, formatted
252	     * {@code 'HH-<HEX12>'} where HEX12 is the first twelve upper-case hex characters
253	     * of the SHA-256 digest of the normalized lastName and address joined by '|'.
254	     * Owners in the same household (same normalized lastName and address) therefore
255	     * derive an identical householdId.
256	     */
257	    private static String householdId(String lastNameKey, String addressKey) {
258	        String source = lastNameKey + "|" + addressKey;
259	        try {
260	            byte[] digest = MessageDigest.getInstance("SHA-256")
261	                .digest(source.getBytes(StandardCharsets.UTF_8));
262	            StringBuilder sb = new StringBuilder(digest.length * 2);
263	            for (byte b : digest) {
264	                sb.append(String.format("%02x", b));
265	            }
266	            return "HH-" + sb.substring(0, 12).toUpperCase(Locale.ROOT);
267	        }
268	        catch (NoSuchAlgorithmException e) {
269	            throw new IllegalStateException("SHA-256 not available", e);
270	        }
271	    }
272	
273	    /**
274	     * Build the customer code assigned on create, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}:
275	     * CITY3 is the upper-cased first three letters of {@code city}, LAST3 is the upper-cased
276	     * first three letters of {@code lastName} and NNNN is a per-city 4-digit zero-padded
277	     * sequence equal to one more than the number of owners already in that city
278	     * (e.g. 'LON-SMI-0007').
279	     */
280	    private String nextCustomerCode(String city, String lastName) {
281	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
282	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
283	        String cityKey = normalizeIdentity(city);
284	        int sequence = (int) this.clinicService.findAllOwners().stream()
285	            .filter(existing -> normalizeIdentity(existing.getCity()).equals(cityKey))
286	            .count() + 1;
287	        return String.format("%s-%s-%04d", city3, last3, sequence);
288	    }
289	
290	    /**
291	     * Roll a registration date forward to the next business day: a Saturday or Sunday
292	     * advances to the following Monday, and a weekday is returned unchanged.
293	     */
294	    private static LocalDate toBusinessDay(LocalDate date) {
295	        return switch (date.getDayOfWeek()) {
296	            case SATURDAY -> date.plusDays(2);
297	            case SUNDAY -> date.plusDays(1);
298	            default -> date;
299	        };
300	    }
301	
302	    /**
303	     * Build the membership number assigned on create, formatted
304	     * {@code '<customerCode>-M<YY>'} where YY is the last two digits of the
305	     * {@code registrationDate} year (e.g. 'LON-SMI-0007-M26').
306	     */
307	    private static String membershipNumber(String customerCode, LocalDate registrationDate) {
308	        String yy = String.format("%02d", registrationDate.getYear() % 100);
309	        return customerCode + "-M" + yy;
310	    }
311	
312	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
313	    @Override
314	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
315	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
316	        if (currentOwner == null) {
317	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
318	        }
319	        currentOwner.setAddress(ownerFieldsDto.getAddress());
320	        currentOwner.setCity(ownerFieldsDto.getCity());
321	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
322	        currentOwner.setLastName(ownerFieldsDto.getLastName());
323	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
324	        this.clinicService.saveOwner(currentOwner);
325	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
326	    }
327	
328	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
329	    @Transactional
330	    @Override
331	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
332	        Owner owner = this.clinicService.findOwnerById(ownerId);
333	        if (owner == null) {
334	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
335	        }
336	        this.clinicService.deleteOwner(owner);
337	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
338	    }
339	
340	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
341	    @Override
342	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
343	        Owner owner = this.clinicService.findOwnerById(ownerId);
344	        if (owner == null) {
345	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
346	        }
347	        HttpHeaders headers = new HttpHeaders();
348	        Pet pet = petMapper.toPet(petFieldsDto);
349	        owner.setId(ownerId);
350	        pet.setOwner(owner);
351	        pet.getType().setName(null);
352	        this.clinicService.savePet(pet);
353	        PetDto petDto = petMapper.toPetDto(pet);
354	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
355	            .buildAndExpand(pet.getId()).toUri());
356	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
357	    }
358	
359	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
360	    @Override
361	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
362	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
363	        if (currentOwner != null) {
364	            Pet currentPet = this.clinicService.findPetById(petId);
365	            if (currentPet != null) {
366	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
367	                currentPet.setName(petFieldsDto.getName());
368	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
369	                this.clinicService.savePet(currentPet);
370	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
371	            }
372	        }
373	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
374	    }
375	
376	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
377	    @Override
378	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
379	        HttpHeaders headers = new HttpHeaders();
380	        Visit visit = visitMapper.toVisit(visitFieldsDto);
381	        Pet pet = new Pet();
382	        pet.setId(petId);
383	        visit.setPet(pet);
384	        this.clinicService.saveVisit(visit);
385	        VisitDto visitDto = visitMapper.toVisitDto(visit);
386	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
387	            .buildAndExpand(visit.getId()).toUri());
388	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
389	    }
390	
391	
392	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
393	    @Override
394	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
395	        Owner owner = this.clinicService.findOwnerById(ownerId);
396	        if (owner != null) {
397	            Pet pet = owner.getPet(petId);
398	            if (pet != null) {
399	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
400	            }
401	        }
402	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
403	    }
404	}
